using std::swap;
using std::vector;

void EvenOdd(vector<int>* A_ptr) {
  vector<int>& A = *A_ptr;
  int next_even = 0, next_odd = size(A) - 1;
  while (next_even < next_odd) {
    if (A[next_even] % 2 == 0) {
      ++next_even;
    } else {
      swap(A[next_even], A[next_odd--]);
    }
  }
}

void EvenOddWrapper(TimedExecutor& executor, vector<int> A) {
  std::multiset<int> before(begin(A), end(A));

  executor.Run([&] { EvenOdd(&A); });

  bool in_odd = false;
  for (int a : A) {
    if (a % 2 == 0) {
      if (in_odd) {
        throw TestFailure("Even elements appear in odd part");
      }
    } else {
      in_odd = true;
    }
  }

  std::multiset<int> after(begin(A), end(A));
  if (before != after) {
    throw TestFailure("Elements mismatch");
  }
}

int main(int argc, char* argv[]) {
  std::vector<std::string> args{argv + 1, argv + argc};
  std::vector<std::string> param_names{"executor", "A"};
  return GenericTestMain(args, "even_odd_array.cc", "even_odd_array.tsv",
                         &EvenOddWrapper, DefaultComparator{}, param_names);
}

package epi;

import epi.test_framework.EpiTest;
import epi.test_framework.GenericTest;
import epi.test_framework.TestFailure;
import epi.test_framework.TimedExecutor;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

public class EvenOddArray {

  public static void evenOdd(List<Integer> A) {

    int nextEven = 0, nextOdd = A.size() - 1;
    while (nextEven < nextOdd) {
      if (A.get(nextEven) % 2 == 0) {
        nextEven++;
      } else {
        Collections.swap(A, nextEven, nextOdd--);
      }
    }
  }

  @EpiTest(testDataFile = "even_odd_array.tsv")
  public static void evenOddWrapper(TimedExecutor executor, List<Integer> A)
      throws Exception {
    List<Integer> before = new ArrayList<>(A);
    executor.run(() -> evenOdd(A));

    boolean inOdd = false;
    for (int i = 0; i < A.size(); i++) {
      if (A.get(i) % 2 == 0) {
        if (inOdd) {
          throw new TestFailure("Even elements appear in odd part");
        }
      } else {
        inOdd = true;
      }
    }
    List<Integer> after = new ArrayList<>(A);
    Collections.sort(before);
    Collections.sort(after);
    if (!before.equals(after)) {
      throw new TestFailure("Elements mismatch");
    }
  }

  public static void main(String[] args) {
    System.exit(
        GenericTest
            .runFromAnnotations(args, "EvenOddArray.java",
                                new Object() {}.getClass().getEnclosingClass())
            .ordinal());
  }
}

using System;
using System.Collections.Generic;
using System.Linq;
using EpiJudge.TestFramework;

public class Solution
{
    public void DutchFlagPartition(int pivotIndex, List<int> values)
    {
        int pivot = values[pivotIndex];
        int smaller = 0, current = 0, larger = values.Count;
        while (current < larger)
        {
            if (values[current] < pivot)
            {
                (values[smaller], values[current]) = (values[current], values[smaller]);
                smaller++;
                current++;
            }
            else if (values[current] == pivot)
                current++;
            else
            {
                larger--;
                (values[current], values[larger]) = (values[larger], values[current]);
            }
        }
    }
}

function dutchFlagPartition(pivotIndex, values) {
  const pivot = values[pivotIndex];
  let smaller = 0,
    current = 0,
    larger = values.length;
  while (current < larger) {
    if (values[current] < pivot) {
      [values[smaller], values[current]] = [values[current], values[smaller]];
      smaller++;
      current++;
    } else if (values[current] === pivot) current++;
    else {
      larger--;
      [values[current], values[larger]] = [values[larger], values[current]];
    }
  }
}

