  // Given n, return all primes up to and including n.
  public static List<Integer> generatePrimes(int n) {

    if (n < 2) {
      return Collections.emptyList();
    }
    final int size = (int)Math.floor(0.5 * (n - 3)) + 1;
    List<Integer> primes = new ArrayList<>();
    primes.add(2);
