public class Solution
{
    public BinaryTreeNode<int>? RebuildBstFromPreorder(List<int> preorder_sequence)
    {
        if (preorder_sequence.Count == 0)
            return null;
        var root = new BinaryTreeNode<int>(preorder_sequence[0]);
        var ancestors = new Stack<BinaryTreeNode<int>>();
        ancestors.Push(root);
        foreach (int value in preorder_sequence.Skip(1))
        {
            var node = new BinaryTreeNode<int>(value);
            if (value < ancestors.Peek().Data)
                ancestors.Peek().Left = node;
            else
            {
                BinaryTreeNode<int>? parent = null;
                while (ancestors.Count > 0 && value >= ancestors.Peek().Data)
                    parent = ancestors.Pop();
                parent!.Right = node;
            }
            ancestors.Push(node);
        }
        return root;
    }
}

function rebuildBstFromPreorder(preorder_sequence) {
  if (!preorder_sequence.length) return null;
  const root = new BinaryTreeNode(preorder_sequence[0]),
    ancestors = [root];
  for (let i = 1; i < preorder_sequence.length; i++) {
    const value = preorder_sequence[i],
      node = new BinaryTreeNode(value);
    if (value < ancestors.at(-1).data) {
      ancestors.at(-1).left = node;
      node.parent = ancestors.at(-1);
    } else {
      let parent = null;
      while (ancestors.length && value >= ancestors.at(-1).data)
        parent = ancestors.pop();
      parent.right = node;
      node.parent = parent;
    }
    ancestors.push(node);
  }
  return root;
}

