public class Solution
{
    public List<double> GenerateFirstKABSqrt2(int k)
    {
        if (k <= 0)
            return [];
        var pairs = new List<(int A, int B)> { (0, 0) };
        var result = new List<double> { 0 };
        int plusOne = 0, plusRoot = 0;
        double root = Math.Sqrt(2);
        while (result.Count < k)
        {
            var first = (A: pairs[plusOne].A + 1, B: pairs[plusOne].B);
            var second = (A: pairs[plusRoot].A, B: pairs[plusRoot].B + 1);
            double x = first.A + first.B * root, y = second.A + second.B * root;
            var next = x <= y ? first : second;
            pairs.Add(next);
            result.Add(next.A + next.B * root);
            if (first == next)
                plusOne++;
            if (second == next)
                plusRoot++;
        }
        return result;
    }
}

function generateFirstKABSqrt2(k) {
  if (k <= 0) return [];
  const pairs = [[0, 0]],
    result = [0],
    root = Math.sqrt(2);
  let plusOne = 0,
    plusRoot = 0;
  while (result.length < k) {
    const first = [pairs[plusOne][0] + 1, pairs[plusOne][1]],
      second = [pairs[plusRoot][0], pairs[plusRoot][1] + 1],
      x = first[0] + first[1] * root,
      y = second[0] + second[1] * root,
      next = x <= y ? first : second;
    pairs.push(next);
    result.push(next[0] + next[1] * root);
    if (first[0] === next[0] && first[1] === next[1]) plusOne++;
    if (second[0] === next[0] && second[1] === next[1]) plusRoot++;
  }
  return result;
}

