public class Solution
{
    public BinaryTreeNode<int>? BuildMinHeightBstFromSortedArray(List<int> values)
    {
        BinaryTreeNode<int>? Build(int start, int end)
        {
            if (start >= end)
                return null;
            int middle = start + (end - start) / 2;
            return new BinaryTreeNode<int>(values[middle])
            {
                Left = Build(start, middle),
                Right = Build(middle + 1, end)
            };
        }
        return Build(0, values.Count);
    }
}

function buildMinHeightBstFromSortedArray(values) {
  function build(start, end, parent = null) {
    if (start >= end) return null;
    const middle = start + Math.floor((end - start) / 2),
      node = new BinaryTreeNode(values[middle]);
    node.parent = parent;
    node.left = build(start, middle, node);
    node.right = build(middle + 1, end, node);
    node.size = end - start;
    return node;
  }
  return build(0, values.length);
}

