public class Solution
{
    public List<int> RangeLookupInBst(BinaryTreeNode<int>? tree, (int, int) i)
    {
        var values = new List<int>();
        void Visit(BinaryTreeNode<int>? node)
        {
            if (node is null)
                return;
            if (node.Data >= i.Item1)
                Visit(node.Left);
            if (node.Data >= i.Item1 && node.Data <= i.Item2)
                values.Add(node.Data);
            if (node.Data <= i.Item2)
                Visit(node.Right);
        }
        Visit(tree);
        return values;
    }
}

function rangeLookupInBst(tree, i) {
  const result = [];
  function visit(node) {
    if (!node) return;
    if (node.data >= i[0]) visit(node.left);
    if (node.data >= i[0] && node.data <= i[1]) result.push(node.data);
    if (node.data <= i[1]) visit(node.right);
  }
  visit(tree);
  return result;
}

