public class Solution
{
    public int FindSuccessor(BinaryTreeNode<int>? tree, int node_idx)
    {
        var stack = new Stack<BinaryTreeNode<int>>();
        if (tree is not null)
            stack.Push(tree);
        BinaryTreeNode<int>? node = null;
        while (stack.TryPop(out var current))
        {
            if (current.Data == node_idx)
            {
                node = current;
                break;
            }
            if (current.Right is not null)
                stack.Push(current.Right);
            if (current.Left is not null)
                stack.Push(current.Left);
        }
        if (node is null)
            return -1;
        if (node.Right is not null)
        {
            node = node.Right;
            while (node.Left is not null)
                node = node.Left;
            return node.Data;
        }
        while (node.Parent is not null && ReferenceEquals(node.Parent.Right, node))
            node = node.Parent;
        return node.Parent?.Data ?? -1;
    }
}

function findSuccessor(tree, node_idx) {
  const stack = tree ? [tree] : [];
  let node = null;
  while (stack.length) {
    const current = stack.pop();
    if (current.data === node_idx) {
      node = current;
      break;
    }
    if (current.right) stack.push(current.right);
    if (current.left) stack.push(current.left);
  }
  if (!node) return -1;
  if (node.right) {
    node = node.right;
    while (node.left) node = node.left;
    return node.data;
  }
  while (node.parent && node.parent.right === node) node = node.parent;
  return node.parent ? node.parent.data : -1;
}

