{
    public BinaryTreeNode<int>? ReconstructPreorder(List<string> data)
    {
        int position = 0;
        BinaryTreeNode<int>? Build()
        {
            if (position >= data.Count)
                return null;
            string token = data[position++];
            if (token == "null")
                return null;
            var root = new BinaryTreeNode<int>(int.Parse(token, System.Globalization.CultureInfo.InvariantCulture));
            root.Left = Build();
            root.Right = Build();
            if (root.Left is not null)
                root.Left.Parent = root;
            if (root.Right is not null)
                root.Right.Parent = root;
            return root;
        }
        return Build();
    }
}

function reconstructPreorder(data) {
  let position = 0;
  function build() {
    if (position >= data.length) return null;
    const token = data[position++];
    if (token === "null" || token === null) return null;
    const root = new BinaryTreeNode(Number(token));
    root.left = build();
    root.right = build();
    if (root.left) root.left.parent = root;
    if (root.right) root.right.parent = root;
    root.size =
      1 + (root.left ? root.left.size : 0) + (root.right ? root.right.size : 0);
    return root;
  }
  return build();
}

