int LevenshteinDistance(const string& A, const string& B) {
  vector<vector<int>> distance_between_prefixes(size(A),
                                                vector<int>(size(B), -1));
  return ComputeDistanceBetweenPrefixes(
      A, size(A) - 1, B, size(B) - 1,
