public class Solution
{
    public int ComputeBinomialCoefficient(int n, int k)
    {
        if (k < 0 || k > n)
            return 0;
        k = Math.Min(k, n - k);
        long result = 1;
        for (int i = 1; i <= k; i++)
            result = result * (n - k + i) / i;
        return (int)result;
    }
}

function computeBinomialCoefficient(n, k) {
  if (k < 0 || k > n) return 0;
  k = Math.min(k, n - k);
  let result = 1n;
  for (let i = 1; i <= k; i++)
    result = (result * BigInt(n - k + i)) / BigInt(i);
  return Number(result);
}

