public class Solution
{
    public List<string> DecomposeIntoDictionaryWords(string domain, HashSet<string> dictionary)
    {
        var previous = Enumerable.Repeat(-1, domain.Length + 1).ToArray();
        previous[0] = 0;
        for (int end = 1; end <= domain.Length; end++)
            for (int start = 0; start < end; start++)
                if (previous[start] != -1 && dictionary.Contains(domain[start..end]))
                {
                    previous[end] = start;
                    break;
                }
        if (previous[^1] == -1)
            return new List<string>();
        var words = new List<string>();
        for (int end = domain.Length; end > 0; end = previous[end])
            words.Add(domain[previous[end]..end]);
        words.Reverse();
        return words;
    }
}

function decomposeIntoDictionaryWords(domain, dictionary) {
  dictionary = new Set(dictionary);
  const previous = Array(domain.length + 1).fill(-1);
  previous[0] = 0;
  for (let end = 1; end <= domain.length; end++)
    for (let start = 0; start < end; start++)
      if (previous[start] !== -1 && dictionary.has(domain.slice(start, end))) {
        previous[end] = start;
        break;
      }
  if (previous.at(-1) === -1) return [];
  const words = [];
  for (let end = domain.length; end > 0; end = previous[end])
    words.push(domain.slice(previous[end], end));
  return words.reverse();
}

module.exports = { decomposeIntoDictionaryWords };

def decompose_into_dictionary_words(domain, dictionary):
    previous = [-1] * (len(domain) + 1)
    previous[0] = 0
    for end in range(1, len(domain) + 1):
        for start in range(end):
            if previous[start] >= 0 and domain[start:end] in dictionary:
                previous[end] = start
                break
    if previous[-1] < 0:
        return []
    result = []
    end = len(domain)
    while end:
        result.append(domain[previous[end]:end])
        end = previous[end]
    result.reverse()
    return result

