public class Solution
{
    public int MaximumRevenue(List<int> coins)
    {
        int n = coins.Count;
        if (n == 0)
            return 0;
        var best = new int[n, n];
        int Value(int left, int right) => left > right ? 0 : best[left, right];
        for (int length = 1; length <= n; length++)
            for (int left = 0; left + length <= n; left++)
            {
                int right = left + length - 1;
                int takeLeft = coins[left] + Math.Min(Value(left + 2, right), Value(left + 1, right - 1));
                int takeRight = coins[right] + Math.Min(Value(left + 1, right - 1), Value(left, right - 2));
                best[left, right] = Math.Max(takeLeft, takeRight);
            }
        return best[0, n - 1];
    }
}

function maximumRevenue(coins) {
  const n = coins.length;
  if (!n) return 0;
  const best = Array.from({ length: n }, () => Array(n).fill(0));
  const value = (l, r) => (l > r ? 0 : best[l][r]);
  for (let size = 1; size <= n; size++)
    for (let l = 0; l + size <= n; l++) {
      const r = l + size - 1;
      best[l][r] = Math.max(
        coins[l] + Math.min(value(l + 2, r), value(l + 1, r - 1)),
        coins[r] + Math.min(value(l + 1, r - 1), value(l, r - 2)),
      );
    }
  return best[0][n - 1];
}

