                           coins, a + 1, b - 1, maximum_revenue_for_range_ptr),
                       ComputeMaximumRevenueForRange(
                           coins, a, b - 2, maximum_revenue_for_range_ptr));
    maximum_revenue_for_range[a][b] = max(max_revenue_a, max_revenue_b);
  }
