                     (a > 0 ? prefixSum.get(a - 1) : 0) -
                     maximumRevenueAlternativeHelper(coins, a, b - 1, prefixSum,
                                                     maximumRevenueForRange)));
    }
    return maximumRevenueForRange.get(a).get(b);
  }

