using System;
using System.Collections.Generic;
using System.Linq;
using EpiJudge.TestFramework;

public class Solution
{
    public List<(int Row, int Column)> SearchMaze(List<List<int>> maze, (int Row, int Column) start, (int Row, int Column) end)
    {
        bool White((int Row, int Column) p) => p.Row >= 0 && p.Row < maze.Count && p.Column >= 0 && p.Column < maze[p.Row].Count && maze[p.Row][p.Column] == 0;
        if (!White(start) || !White(end))
            return new();
        var previous = new Dictionary<(int Row, int Column), (int Row, int Column)> { [start] = start };
        var pending = new Queue<(int Row, int Column)>();
        pending.Enqueue(start);
        (int Row, int Column)[] steps = [(1, 0), (-1, 0), (0, 1), (0, -1)];
        while (pending.TryDequeue(out var cell))
        {
            if (cell == end)
            {
                var path = new List<(int Row, int Column)>();
                for (var p = end; ; p = previous[p])
                {
                    path.Add(p);
                    if (p == start)
                        break;
                }
                path.Reverse();
                return path;
            }
            foreach (var step in steps)
            {
                var neighbor = (Row: cell.Row + step.Row, Column: cell.Column + step.Column);
                if (White(neighbor) && previous.TryAdd(neighbor, cell))
                    pending.Enqueue(neighbor);
            }
        }
        return new();
    }
}

function searchMaze(maze, start, end) {
  const white = ([r, c]) =>
      r >= 0 &&
      r < maze.length &&
      c >= 0 &&
      c < maze[r].length &&
      maze[r][c] === 0,
    key = ([r, c]) => r + "," + c;
  if (!white(start) || !white(end)) return [];
  const previous = new Map([[key(start), null]]),
    cells = new Map([[key(start), start]]),
    pending = [start];
  for (let head = 0; head < pending.length; head++) {
    const cell = pending[head];
    if (key(cell) === key(end)) {
      const path = [];
      for (let at = key(end); at !== null; at = previous.get(at))
        path.push(cells.get(at));
      return path.reverse();
    }
    for (const [dr, dc] of [
      [1, 0],
      [-1, 0],
      [0, 1],
      [0, -1],
    ]) {
      const next = [cell[0] + dr, cell[1] + dc],
        id = key(next);
      if (white(next) && !previous.has(id)) {
        previous.set(id, key(cell));
        cells.set(id, next);
        pending.push(next);
      }
    }
  }
  return [];
}

