bool Bfs(GraphVertex* s) {
  s->d = 0;
  queue<GraphVertex*> q;
  q.emplace(s);

  while (!empty(q)) {
    for (GraphVertex*& t : q.front()->edges) {
      if (t->d == -1) {  // Unvisited vertex.
        t->d = q.front()->d + 1;
        q.emplace(t);
      } else if (t->d == q.front()->d) {
        return false;
      }
    }
    q.pop();
  }
  return true;
}

