public class Solution
{
    public int TransformString(HashSet<string> D, string s, string t)
    {
        if (s == t)
            return 0;
        var remaining = new HashSet<string>(D);
        remaining.Remove(s);
        var queue = new Queue<(string Word, int Distance)>();
        queue.Enqueue((s, 0));
        while (queue.TryDequeue(out var entry))
        {
            var chars = entry.Word.ToCharArray();
            for (int i = 0; i < chars.Length; i++)
            {
                char old = chars[i];
                for (char c = 'a'; c <= 'z'; c++)
                {
                    if (c == old)
                        continue;
                    chars[i] = c;
                    var candidate = new string(chars);
                    if (!remaining.Remove(candidate))
                        continue;
                    if (candidate == t)
                        return entry.Distance + 1;
                    queue.Enqueue((candidate, entry.Distance + 1));
                }
                chars[i] = old;
            }
        }
        return -1;
    }
}

function transformString(D, s, t) {
  if (s === t) return 0;
  const remaining = new Set(D),
    queue = [[s, 0]];
  remaining.delete(s);
  for (let head = 0; head < queue.length; head++) {
    const [word, distance] = queue[head],
      chars = word.split("");
    for (let i = 0; i < chars.length; i++) {
      const old = chars[i];
      for (let code = 97; code <= 122; code++) {
        const c = String.fromCharCode(code);
        if (c === old) continue;
        chars[i] = c;
        const candidate = chars.join("");
        if (!remaining.delete(candidate)) continue;
        if (candidate === t) return distance + 1;
        queue.push([candidate, distance + 1]);
      }
      chars[i] = old;
    }
  }
  return -1;
}

