public class Solution
{
    public int FindLargestNumberTeams(int k, List<(int, int)> edges)
    {
        var outgoing = Enumerable.Range(0, k).Select(_ => new List<int>()).ToArray();
        int[] incoming = new int[k], length = Enumerable.Repeat(1, k).ToArray();
        foreach (var (from, to) in edges)
        {
            outgoing[from].Add(to);
            incoming[to]++;
        }
        var ready = new Queue<int>();
        for (int i = 0; i < k; i++)
        if (incoming[i] == 0)
            ready.Enqueue(i);
        int best = 0;
        while (ready.TryDequeue(out int team))
        {
            best = Math.Max(best, length[team]);
            foreach (int next in outgoing[team])
            {
                length[next] = Math.Max(length[next], length[team] + 1);
                if (--incoming[next] == 0)
                    ready.Enqueue(next);
            }
        }
        return best;
    }
}

function findLargestNumberTeams(k, edges) {
  const outgoing = Array.from({ length: k }, () => []),
    incoming = Array(k).fill(0),
    length = Array(k).fill(1),
    ready = [];
  for (const [from, to] of edges) {
    outgoing[from].push(to);
    incoming[to]++;
  }
  for (let i = 0; i < k; i++) if (incoming[i] === 0) ready.push(i);
  let best = 0;
  for (let head = 0; head < ready.length; head++) {
    const team = ready[head];
    best = Math.max(best, length[team]);
    for (const next of outgoing[team]) {
      length[next] = Math.max(length[next], length[team] + 1);
      if (--incoming[next] === 0) ready.push(next);
    }
  }
  return best;
}

