int GetMaxTrappedWater(const vector<int>& heights) {
  int i = 0, j = size(heights) - 1, max_water = 0;
  while (i < j) {
    int width = j - i;
    max_water = max(max_water, width * min(heights[i], heights[j]));
    if (heights[i] > heights[j]) {
      --j;
    } else {  // heights[i] <= heights[j].
      ++i;
    }
  }
  return max_water;
}

