public class Solution
{
    private int limit;
    private readonly LinkedList<(int Key, int Price)> order = new();
    private readonly Dictionary<int, LinkedListNode<(int Key, int Price)>> entries = new();
    public void Initialize(int capacity)
    {
        limit = capacity;
        entries.Clear();
        order.Clear();
    }
    public int Lookup(int isbn)
    {
        if (!entries.TryGetValue(isbn, out var node))
            return -1;
        order.Remove(node);
        order.AddFirst(node);
        return node.Value.Price;
    }
    public void Insert(int isbn, int price)
    {
        if (entries.TryGetValue(isbn, out var existing))
        {
            order.Remove(existing);
            order.AddFirst(existing);
            return;
        }
        if (limit <= 0)
            return;
        if (entries.Count == limit)
        {
            var last = order.Last!;
            entries.Remove(last.Value.Key);
            order.RemoveLast();
        }
        entries[isbn] = order.AddFirst((isbn, price));
    }
    public bool Erase(int isbn)
    {
        if (!entries.Remove(isbn, out var node))
            return false;
        order.Remove(node);
        return true;
    }
}

class LruCache {
  constructor(capacity) {
    this.limit = capacity;
    this.entries = new Map();
  }
  lookup(isbn) {
    if (!this.entries.has(isbn)) return -1;
    const price = this.entries.get(isbn);
    this.entries.delete(isbn);
    this.entries.set(isbn, price);
    return price;
  }
  insert(isbn, price) {
    if (this.entries.has(isbn)) {
      this.lookup(isbn);
      return;
    }
    if (this.limit <= 0) return;
    if (this.entries.size === this.limit)
      this.entries.delete(this.entries.keys().next().value);
    this.entries.set(isbn, price);
  }
  erase(isbn) {
    return this.entries.delete(isbn);
  }
}
