public class Solution
{
    public int FindNearestRepetition(List<string> paragraph)
    {
        var last = new Dictionary<string, int>();
        int best = int.MaxValue;
        for (int i = 0; i < paragraph.Count; i++)
        {
            if (last.TryGetValue(paragraph[i], out int previous))
                best = Math.Min(best, i - previous);
            last[paragraph[i]] = i;
        }
        return best == int.MaxValue ? -1 : best;
    }
}

function findNearestRepetition(paragraph) {
  const last = new Map();
  let best = Infinity;
  for (let i = 0; i < paragraph.length; i++) {
    if (last.has(paragraph[i]))
      best = Math.min(best, i - last.get(paragraph[i]));
    last.set(paragraph[i], i);
  }
  return best === Infinity ? -1 : best;
}

