using EpiJudge.TestFramework;

public class Solution
{
    public int LongestContainedRange(List<int> A)
    {
        var unseen = A.ToHashSet();
        int best = 0;
        foreach (int value in A)
        {
            if (!unseen.Remove(value))
                continue;
            int size = 1;
            for (long x = (long)value - 1; x >= int.MinValue && unseen.Remove((int)x); x--)
                size++;
            for (long x = (long)value + 1; x <= int.MaxValue && unseen.Remove((int)x); x++)
                size++;
            best = Math.Max(best, size);
        }
        return best;
    }
}

function longestContainedRange(A) {
  const unseen = new Set(A);
  let best = 0;
  for (const value of A) {
    if (!unseen.delete(value)) continue;
    let size = 1;
    for (let x = value - 1; x >= -2147483648 && unseen.delete(x); x--) size++;
    for (let x = value + 1; x <= 2147483647 && unseen.delete(x); x++) size++;
    best = Math.max(best, size);
  }
  return best;
}

