public class Solution
{
    public bool TestCollatzConjecture(int n)
    {
        for (long start = 3; start <= n; start += 2)
        {
            var seen = new HashSet<long>();
            long value = start;
            while (value >= start)
            {
                if (!seen.Add(value))
                    return false;
                if ((value & 1) == 0)
                    value /= 2;
                else
                    value = checked(3 * value + 1);
            }
        }
        return true;
    }
}

function testCollatzConjecture(n) {
  for (let start = 3n; start <= BigInt(n); start += 2n) {
    const seen = new Set();
    let value = start;
    while (value >= start) {
      if (seen.has(value)) return false;
      seen.add(value);
      value = value % 2n === 0n ? value / 2n : 3n * value + 1n;
    }
  }
  return true;
}

