public class Solution
{
    public double BuyAndSellStockKTimes(List<double> prices, int k)
    {
        if (k <= 0 || prices.Count < 2)
            return 0;
        if (k >= prices.Count / 2)
        {
            double total = 0;
            for (int i = 1; i < prices.Count; i++)
                total += Math.Max(0, prices[i] - prices[i - 1]);
            return total;
        }
        var holding = Enumerable.Repeat(double.NegativeInfinity, k + 1).ToArray();
        var sold = new double[k + 1];
        foreach (double price in prices)
            for (int transaction = k; transaction >= 1; transaction--)
            {
                sold[transaction] = Math.Max(sold[transaction], holding[transaction] + price);
                holding[transaction] = Math.Max(holding[transaction], sold[transaction - 1] - price);
            }
        return sold[k];
    }
}

function buyAndSellStockKTimes(prices, k) {
  if (k <= 0 || prices.length < 2) return 0;
  if (k >= Math.floor(prices.length / 2)) {
    let total = 0;
    for (let i = 1; i < prices.length; i++)
      total += Math.max(0, prices[i] - prices[i - 1]);
    return total;
  }
  const holding = Array(k + 1).fill(-Infinity),
    sold = Array(k + 1).fill(0);
  for (const price of prices)
    for (let transaction = k; transaction >= 1; transaction--) {
      sold[transaction] = Math.max(
        sold[transaction],
        holding[transaction] + price,
      );
      holding[transaction] = Math.max(
        holding[transaction],
        sold[transaction - 1] - price,
      );
    }
  return sold[k];
}

