public class Solution
{
    public List<int> RotateArray(List<int> A, int rotate_amount)
    {
        if (A.Count == 0)
            return A;
        int amount = rotate_amount % A.Count;
        if (amount < 0)
            amount += A.Count;
        A.Reverse();
        A.Reverse(0, amount);
        A.Reverse(amount, A.Count - amount);
        return A;
    }
}

function rotateArray(A, rotate_amount) {
  if (!A.length) return A;
  const amount = ((rotate_amount % A.length) + A.length) % A.length;
  function reverse(l, r) {
    while (l < r) {
      [A[l], A[r]] = [A[r], A[l]];
      l++;
      r--;
    }
  }
  reverse(0, A.length - 1);
  reverse(0, amount - 1);
  reverse(amount, A.length - 1);
  return A;
}

