public class Solution
{
    public int LongestMatchingParentheses(string s)
    {
        var openings = new Stack<int>();
        openings.Push(-1);
        int best = 0;
        for (int i = 0; i < s.Length; i++)
        {
            if (s[i] == '(')
                openings.Push(i);
            else
            {
                openings.Pop();
                if (openings.Count == 0)
                    openings.Push(i);
                else
                    best = Math.Max(best, i - openings.Peek());
            }
        }
        return best;
    }
}

function longestMatchingParentheses(s) {
  const openings = [-1];
  let best = 0;
  for (let i = 0; i < s.length; i++) {
    if (s[i] === "(") openings.push(i);
    else {
      openings.pop();
      if (!openings.length) openings.push(i);
      else best = Math.max(best, i - openings.at(-1));
    }
  }
  return best;
}

