public class Solution
{
    public BinaryTreeNode<int>? BuildBstFromSortedDoublyList(BinaryTreeNode<int>? head, int count)
    {
        var cursor = head;
        BinaryTreeNode<int>? Build(int size)
        {
            if (size == 0)
                return null;
            var left = Build(size / 2);
            var root = cursor!;
            cursor = cursor!.Right;
            root.Left = left;
            root.Right = Build(size - size / 2 - 1);
            if (root.Left is not null)
                root.Left.Parent = root;
            if (root.Right is not null)
                root.Right.Parent = root;
            return root;
        }
        return Build(count);
    }
}

function buildBstFromSortedDoublyList(head, count) {
  let cursor = head;
  function build(size) {
    if (!size) return null;
    const left = build(Math.floor(size / 2)),
      root = cursor;
    cursor = cursor.right;
    root.left = left;
    root.right = build(size - Math.floor(size / 2) - 1);
    root.parent = null;
    if (root.left) root.left.parent = root;
    if (root.right) root.right.parent = root;
    root.size = size;
    return root;
  }
  return build(count);
}

