public class Solution
{
    public BinaryTreeNode<int>? BstToDoublyLinkedList(BinaryTreeNode<int>? tree)
    {
        var stack = new Stack<BinaryTreeNode<int>>();
        BinaryTreeNode<int>? head = null, previous = null, current = tree;
        while (current is not null || stack.Count > 0)
        {
            while (current is not null)
            {
                stack.Push(current);
                current = current.Left;
            }
            current = stack.Pop();
            var right = current.Right;
            current.Left = previous;
            if (previous is null)
                head = current;
            else
                previous.Right = current;
            previous = current;
            current = right;
        }
        if (previous is not null)
            previous.Right = null;
        return head;
    }
}

function bstToDoublyLinkedList(tree) {
  const stack = [];
  let head = null,
    previous = null,
    current = tree;
  while (current || stack.length) {
    while (current) {
      stack.push(current);
      current = current.left;
    }
    current = stack.pop();
    const right = current.right;
    current.left = previous;
    if (!previous) head = current;
    else previous.right = current;
    previous = current;
    current = right;
  }
  if (previous) previous.right = null;
  return head;
}

