public class Solution
{
    public bool IsMatch(string regex, string s)
    {
        bool anchored = regex.StartsWith('^');
        int first = anchored ? 1 : 0;
        var memo = new Dictionary<(int Pattern, int Text), bool>();
        bool Match(int p, int t)
        {
            if (memo.TryGetValue((p, t), out bool known))
                return known;
            bool result;
            if (p == regex.Length)
                result = true;
            else if (p == regex.Length - 1 && regex[p] == '$')
                result = t == s.Length;
            else
            {
                bool fits = t < s.Length && (regex[p] == '.' || regex[p] == s[t]);
                result = p + 1 < regex.Length && regex[p + 1] == '*'
                    ? Match(p + 2, t) || (fits && Match(p, t + 1))
                    : fits && Match(p + 1, t + 1);
            }
            memo[(p, t)] = result;
            return result;
        }
        if (anchored)
            return Match(first, 0);
        for (int start = 0; start <= s.Length; start++)
            if (Match(first, start))
                return true;
        return false;
    }
}

function isMatch(regex, s) {
  const anchored = regex.startsWith("^"),
    first = anchored ? 1 : 0,
    memo = new Map();
  function match(p, t) {
    const key = p + "," + t;
    if (memo.has(key)) return memo.get(key);
    let result;
    if (p === regex.length) result = true;
    else if (p === regex.length - 1 && regex[p] === "$")
      result = t === s.length;
    else {
      const fits = t < s.length && (regex[p] === "." || regex[p] === s[t]);
      result =
        p + 1 < regex.length && regex[p + 1] === "*"
          ? match(p + 2, t) || (fits && match(p, t + 1))
          : fits && match(p + 1, t + 1);
    }
    memo.set(key, result);
    return result;
  }
  if (anchored) return match(first, 0);
  for (let start = 0; start <= s.length; start++)
    if (match(first, start)) return true;
  return false;
}

