public class RegularExpression {
  @EpiTest(testDataFile = "regular_expression.tsv")

  public static boolean isMatch(String regex, String s) {

    // Case (2.): regex starts with '^'.
    if (regex.charAt(0) == '^') {
      return isMatchHere(regex.substring(1), s);
    }

    for (int i = 0; i <= s.length(); ++i) {
      if (isMatchHere(regex, s.substring(i))) {
        return true;
      }
    }
    return false;
  }

  private static boolean isMatchHere(String regex, String s) {
    if (regex.isEmpty()) {
      // Case (1.): Empty regex matches all strings.
      return true;
    }

    if ("$".equals(regex)) {
      // Case (2): Reach the end of regex, and last char is '$'.
      return s.isEmpty();
    }

    if (regex.length() >= 2 && regex.charAt(1) == '*') {
      // Case (3.): A '*' match.
      // Iterate through s, checking '*' condition, if '*' condition holds,
      // performs the remaining checks.
      for (int i = 0; i < s.length() && (regex.charAt(0) == '.' ||
                                         regex.charAt(0) == s.charAt(i));
           ++i) {
        if (isMatchHere(regex.substring(2), s.substring(i + 1))) {
          return true;
        }
      }
      // See '*' matches zero character in s.
      return isMatchHere(regex.substring(2), s);
    }

    // Case (4.): regex begins with single character match.
    return !s.isEmpty() &&
        (regex.charAt(0) == '.' || regex.charAt(0) == s.charAt(0)) &&
        isMatchHere(regex.substring(1), s.substring(1));
  }

  public static void main(String[] args) {
    System.exit(
        GenericTest
            .runFromAnnotations(args, "RegularExpression.java",
                                new Object() {}.getClass().getEnclosingClass())
            .ordinal());
  }
}

public class Solution
{
    public bool ExpressionSynthesis(List<int> digits, int target)
    {
        bool Search(int index, long total, long lastTerm)
        {
            if (index == digits.Count)
                return total == target;
            long value = 0;
            for (int end = index; end < digits.Count; end++)
            {
                value = value * 10 + digits[end];
                if (index == 0)
                {
                    if (Search(end + 1, value, value))
                        return true;
                }
                else if (Search(end + 1, total + value, value) ||
                         Search(end + 1, total - lastTerm + lastTerm * value, lastTerm * value))
                    return true;
            }
            return false;
        }
        return digits.Count > 0 && Search(0, 0, 0);
    }
}

function expressionSynthesis(digits, target) {
  target = BigInt(target);
  function search(index, total, last) {
    if (index === digits.length) return total === target;
    let value = 0n;
    for (let end = index; end < digits.length; end++) {
      value = value * 10n + BigInt(digits[end]);
      if (index === 0) {
        if (search(end + 1, value, value)) return true;
      } else if (
        search(end + 1, total + value, value) ||
        search(end + 1, total - last + last * value, last * value)
      )
        return true;
    }
    return false;
  }
  return digits.length > 0 && search(0, 0n, 0n);
}

