public class Solution
{
    public double HuffmanEncoding(List<(string, double)> symbols)
    {
        var weights = new PriorityQueue<double, double>();
        foreach (var (_, frequency) in symbols)
            weights.Enqueue(frequency, frequency);
        double cost = 0;
        while (weights.Count > 1)
        {
            double combined = weights.Dequeue() + weights.Dequeue();
            cost += combined;
            weights.Enqueue(combined, combined);
        }
        return cost / 100.0;
    }
}

function huffmanEncoding(symbols) {
  class Heap {
    constructor(compare) {
      this.a = [];
      this.compare = compare;
    }
    get size() {
      return this.a.length;
    }
    peek() {
      return this.a[0];
    }
    push(value) {
      const a = this.a;
      a.push(value);
      let i = a.length - 1;
      while (i) {
        const p = Math.floor((i - 1) / 2);
        if (this.compare(a[p], a[i]) <= 0) break;
        [a[p], a[i]] = [a[i], a[p]];
        i = p;
      }
    }
    pop() {
      const a = this.a;
      if (!a.length) throw new RangeError("Empty heap");
      const result = a[0],
        last = a.pop();
      if (a.length) {
        a[0] = last;
        let i = 0;
        for (;;) {
          let c = 2 * i + 1;
          if (c >= a.length) break;
          if (c + 1 < a.length && this.compare(a[c + 1], a[c]) < 0) c++;
          if (this.compare(a[i], a[c]) <= 0) break;
          [a[i], a[c]] = [a[c], a[i]];
          i = c;
        }
      }
      return result;
    }
  }
  const weights = new Heap((a, b) => a - b);
  for (const [, frequency] of symbols) weights.push(frequency);
  let cost = 0;
  while (weights.size > 1) {
    const combined = weights.pop() + weights.pop();
    cost += combined;
    weights.push(combined);
  }
  return cost / 100;
}

