public class Solution
{
    public ListNode<int>? CyclicallyRightShiftList(ListNode<int>? L, int k)
    {
        if (L is null)
            return null;
        int length = 1;
        var tail = L;
        while (tail.Next is not null)
        {
            tail = tail.Next;
            length++;
        }
        k %= length;
        if (k == 0)
            return L;
        var newTail = L;
        for (int i = 1; i < length - k; i++)
            newTail = newTail.Next!;
        var newHead = newTail.Next;
        tail.Next = L;
        newTail.Next = null;
        return newHead;
    }
}

function cyclicallyRightShiftList(L, k) {
  if (!L) return null;
  let length = 1,
    tail = L;
  while (tail.next) {
    tail = tail.next;
    length++;
  }
  k = ((k % length) + length) % length;
  if (!k) return L;
  let newTail = L;
  for (let i = 1; i < length - k; i++) newTail = newTail.next;
  const newHead = newTail.next;
  tail.next = L;
  newTail.next = null;
  return newHead;
}

