public class Solution
{
    public ListNode<int>? ListPivoting(ListNode<int>? head, int x)
    {
        var less = new ListNode<int>(0);
        var equal = new ListNode<int>(0);
        var greater = new ListNode<int>(0);
        var lessTail = less;
        var equalTail = equal;
        var greaterTail = greater;
        while (head is not null)
        {
            var next = head.Next;
            head.Next = null;
            if (head.Data < x)
            {
                lessTail.Next = head;
                lessTail = head;
            }
            else if (head.Data == x)
            {
                equalTail.Next = head;
                equalTail = head;
            }
            else
            {
                greaterTail.Next = head;
                greaterTail = head;
            }
            head = next;
        }
        equalTail.Next = greater.Next;
        lessTail.Next = equal.Next;
        return less.Next;
    }
}

function listPivoting(head, x) {
  const heads = [new ListNode(0), new ListNode(0), new ListNode(0)],
    tails = heads.slice();
  while (head) {
    const next = head.next;
    head.next = null;
    const group = head.data < x ? 0 : head.data === x ? 1 : 2;
    tails[group].next = head;
    tails[group] = head;
    head = next;
  }
  tails[1].next = heads[2].next;
  tails[0].next = heads[1].next;
  return heads[0].next;
}

