using System.Collections.Generic;
using System.Linq;
using EpiJudge.TestFramework;

public class Solution
{
    public List<List<int>> NQueens(int n)
    {
        var answer = new List<List<int>>();
        var placement = new List<int>();
        var columns = new HashSet<int>();
        var rising = new HashSet<int>();
        var falling = new HashSet<int>();
        void Place(int row)
        {
            if (row == n)
            {
                answer.Add(new List<int>(placement));
                return;
            }
            for (int c = 0; c < n; c++)
            if (!columns.Contains(c) && !rising.Contains(row + c) && !falling.Contains(row - c))
            {
                columns.Add(c);
                rising.Add(row + c);
                falling.Add(row - c);
                placement.Add(c);
                Place(row + 1);
                placement.RemoveAt(placement.Count - 1);
                columns.Remove(c);
                rising.Remove(row + c);
                falling.Remove(row - c);
            }
        }
        Place(0);
        return answer;
    }
}

function nQueens(n) {
  const answer = [],
    placement = [],
    columns = new Set(),
    rising = new Set(),
    falling = new Set();
  function place(row) {
    if (row === n) {
      answer.push(placement.slice());
      return;
    }
    for (let c = 0; c < n; c++)
      if (!columns.has(c) && !rising.has(row + c) && !falling.has(row - c)) {
        columns.add(c);
        rising.add(row + c);
        falling.add(row - c);
        placement.push(c);
        place(row + 1);
        placement.pop();
        columns.delete(c);
        rising.delete(row + c);
        falling.delete(row - c);
      }
  }
  place(0);
  return answer;
}

