    if (numLeftParensNeeded < numRightParensNeeded) { // Able to insert ')'.
      directedGenerateBalancedParentheses(numLeftParensNeeded,
                                          numRightParensNeeded - 1,
                                          validPrefix + ")", result);
    }
  }

