    if (string prefix = text.substr(offset, i - offset); IsPalindrome(prefix)) {
      partial_partition->emplace_back(prefix);
      DirectedPalindromeDecompositions(text, i, partial_partition, result);
      partial_partition->pop_back();
    }
  }
