public class Solution
{
    public ListNode<int>? StableSortList(ListNode<int>? L)
    {
        if (L?.Next is null)
            return L;
        var slow = L;
        var fast = L.Next;
        while (fast?.Next is not null)
        {
            slow = slow.Next!;
            fast = fast.Next.Next;
        }
        var right = slow.Next;
        slow.Next = null;
        return Merge(StableSortList(L), StableSortList(right));
    }
    private static ListNode<int>? Merge(ListNode<int>? first, ListNode<int>? second)
    {
        var dummy = new ListNode<int>(0);
        var tail = dummy;
        while (first is not null && second is not null)
        {
            if (first.Data <= second.Data)
            {
                tail.Next = first;
                first = first.Next;
            }
            else
            {
                tail.Next = second;
                second = second.Next;
            }
            tail = tail.Next;
        }
        tail.Next = first ?? second;
        return dummy.Next;
    }
}

function stableSortList(L) {
  if (!L || !L.next) return L;
  let slow = L,
    fast = L.next;
  while (fast && fast.next) {
    slow = slow.next;
    fast = fast.next.next;
  }
  const right = slow.next;
  slow.next = null;
  let first = stableSortList(L),
    second = stableSortList(right);
  const dummy = new ListNode(0);
  let tail = dummy;
  while (first && second) {
    if (first.data <= second.data) {
      tail.next = first;
      first = first.next;
    } else {
      tail.next = second;
      second = second.next;
    }
    tail = tail.next;
  }
  tail.next = first || second;
  return dummy.next;
}

