public class Solution
{
    public bool IsWellFormed(string s)
    {
        var openings = new Stack<char>();
        foreach (char c in s)
        {
            if (c is '(' or '[' or '{')
            {
                openings.Push(c);
                continue;
            }
            char expected = c switch
            {
                ')' => '(',
                ']' => '[',
                '}' => '{',
                _ => '\0'
            };
            if (expected == '\0' || !openings.TryPop(out char opening) || opening != expected)
                return false;
        }
        return openings.Count == 0;
    }
}

function isWellFormed(s) {
  const openings = [],
    pairs = { ")": "(", "]": "[", "}": "{" };
  for (const c of s) {
    if (c === "(" || c === "[" || c === "{") {
      openings.push(c);
      continue;
    }
    if (!pairs[c] || !openings.length || openings.pop() !== pairs[c])
      return false;
  }
  return !openings.length;
}

