public class Solution
{
    private int[] buffer = new int[1];
    private int head, count;

    public void Initialize(int capacity)
    {
        buffer = new int[Math.Max(1, capacity)];
        head = count = 0;
    }

    public void Enqueue(int value)
    {
        if (count == buffer.Length)
        {
            var larger = new int[buffer.Length * 2];
            for (int i = 0; i < count; i++)
                larger[i] = buffer[(head + i) % buffer.Length];
            buffer = larger;
            head = 0;
        }
        buffer[(head + count) % buffer.Length] = value;
        count++;
    }

    public int Dequeue()
    {
        if (count == 0)
            throw new InvalidOperationException("The queue is empty.");
        int value = buffer[head];
        head = (head + 1) % buffer.Length;
        count--;
        return value;
    }

    public int Size() => count;
}

class CircularQueue {
  constructor(capacity = 1) {
    this.buffer = Array(Math.max(1, capacity)).fill(0);
    this.head = 0;
    this.count = 0;
  }
  enqueue(value) {
    if (this.count === this.buffer.length) {
      const larger = Array(this.buffer.length * 2).fill(0);
      for (let i = 0; i < this.count; i++)
        larger[i] = this.buffer[(this.head + i) % this.buffer.length];
      this.buffer = larger;
      this.head = 0;
    }
    this.buffer[(this.head + this.count) % this.buffer.length] = value;
    this.count++;
  }
  dequeue() {
    if (!this.count) throw new RangeError("Empty queue");
    const value = this.buffer[this.head];
    this.head = (this.head + 1) % this.buffer.length;
    this.count--;
    return value;
  }
  size() {
    return this.count;
  }
}
