public class Solution
{
    public string ConvertBase(string num_as_string, int b1, int b2)
    {
        const string digits = "0123456789ABCDEF";
        bool negative = num_as_string.StartsWith('-');
        System.Numerics.BigInteger value = 0;
        foreach (char c in num_as_string.AsSpan(negative ? 1 : 0))
            value = value * b1 + digits.IndexOf(char.ToUpperInvariant(c));
        if (value.IsZero)
            return "0";
        var result = new List<char>();
        while (value > 0)
        {
            result.Add(digits[(int)(value % b2)]);
            value /= b2;
        }
        if (negative)
            result.Add('-');
        result.Reverse();
        return new string(result.ToArray());
    }
}

function convertBase(num_as_string, b1, b2) {
  const digits = "0123456789ABCDEF",
    negative = num_as_string.startsWith("-");
  let value = 0n;
  for (let i = negative ? 1 : 0; i < num_as_string.length; i++)
    value =
      value * BigInt(b1) +
      BigInt(digits.indexOf(num_as_string[i].toUpperCase()));
  if (value === 0n) return "0";
  const result = [];
  while (value > 0n) {
    result.push(digits[Number(value % BigInt(b2))]);
    value /= BigInt(b2);
  }
  if (negative) result.push("-");
  return result.reverse().join("");
}

