public class Solution
{
    public int[] ProductExceptSelf(int[] nums)
    {
        var outp = new int[nums.Length];
        int product = 1;
        for (int i = 0; i < nums.Length; i++)
        {
            outp[i] = product;
            product *= nums[i];
        }
        product = 1;
        for (int i = nums.Length - 1; i >= 0; i--)
        {
            outp[i] *= product;
            product *= nums[i];
        }
        return outp;
    }
}

