def combination_sum(candidates: list[int], target: int) -> list[list[int]]:
    out = []
    path = []

    def visit(i, remaining):
        if remaining == 0:
            out.append(path[:])
            return
        for j in range(i, len(candidates)):
            if candidates[j] <= remaining:
                path.append(candidates[j])
                visit(j, remaining - candidates[j])
                path.pop()

    visit(0, target)
    return out


