public class Solution {
  public int[][] combinationSum(int[] candidates, int target) {
    List<int[]> out = new ArrayList<>();
    List<Integer> path = new ArrayList<>();
    class Search {
      void visit(int start, int remaining) {
        if (remaining == 0) {
          out.add(path.stream().mapToInt(v -> v).toArray());
          return;
        }
        for (int i = start; i < candidates.length; i++)
          if (candidates[i] <= remaining) {
            path.add(candidates[i]);
            visit(i, remaining - candidates[i]);
            path.remove(path.size() - 1);
          }
      }
    }
    new Search().visit(0, target);
    return out.toArray(int[][] ::new);
  }
}

