def insert(intervals: list[list[int]], newInterval: list[int]) -> list[list[int]]:
    out = []
    for start, end in sorted(intervals + [newInterval]):
        if out and start <= out[-1][1]:
            out[-1][1] = max(end, out[-1][1])
        else:
            out.append([start, end])
    return out


