    List<int[]> out = new ArrayList<>();
    List<TreeNode> q = new ArrayList<>();
    if (root != null)
      q.add(root);
    while (!q.isEmpty()) {
      out.add(q.stream().mapToInt(n -> n.val).toArray());
      List<TreeNode> next = new ArrayList<>();
      for (TreeNode n : q) {
        if (n.left != null)
          next.add(n.left);
        if (n.right != null)
          next.add(n.right);
      }
      q = next;
    }
    return out.toArray(int[][] ::new);
  }
