public class Solution
{
    public int MinMeetingRooms(int[][] intervals)
    {
        var events = intervals.SelectMany(row => new[] { (time: row[0], delta: 1), (time: row[1], delta: -1) }).OrderBy(e => e.time).ThenBy(e => e.delta);
