    return n == null ? "# " : n.val + " " + serialize(n.left) + serialize(n.right);
  }
  static TreeNode read(Deque<String> q) {
    String s = q.remove();
    if (s.equals("#"))
      return null;
    TreeNode n = new TreeNode(Integer.parseInt(s));
    n.left = read(q);
    n.right = read(q);
