class Solution {
 public:
  std::string MinWindow(std::string s, std::string t) {
    std::array<int, 128> need{};
    for (unsigned char c : t) need[c]++;
    int missing = static_cast<int>(t.size()), left = 0, start = 0,
        length = INT32_MAX;
    for (int r = 0; r < static_cast<int>(s.size()); r++) {
      if (need[static_cast<unsigned char>(s[r])]-- > 0) missing--;
      while (!missing) {
        if (r - left + 1 < length) {
          start = left;
          length = r - left + 1;
        }
        if (++need[static_cast<unsigned char>(s[left++])] > 0) missing++;
      }
    }
    return length == INT32_MAX ? "" : s.substr(start, length);
  }
};

