def count_substrings(s: str) -> int:
    count = 0
    for i in range(len(s)):
        for parity in [0, 1]:
            l, r = i, i + parity
            while l >= 0 and r < len(s) and s[l] == s[r]:
                count += 1
                l -= 1
                r += 1
    return count


