public class Solution
{
    public bool IsValid(string s)
    {
        var stack = new Stack<char>();
        foreach (char c in s)
        {
            if (c is '(' or '[' or '{')
                stack.Push(c);
            else
            {
                int j = ")] }".Replace(" ", "").IndexOf(c);
                if (stack.Count == 0 || stack.Pop() != "([{"[j])
                    return false;
            }
        }
        return stack.Count == 0;
    }
}

