class Solution {
 public:
  bool IsValid(std::string s) {
    std::vector<char> stack;
    for (char c : s) {
      auto i = std::string("([{").find(c);
      if (i != std::string::npos)
        stack.push_back(c);
      else {
        auto j = std::string(")]}").find(c);
        if (stack.empty() || stack.back() != std::string("([{")[j])
          return false;
        stack.pop_back();
      }
    }
    return stack.empty();
  }
};

