    def serialize(n):
        return (
            str(n.val) + " " + Probe.serialize(n.left) + Probe.serialize(n.right)
            if n
            else "# "
        )

    @staticmethod
    def deserialize(s):
        tokens = iter(s.split())

        def read():
            token = next(tokens)
            return None if token == "#" else TreeNode(int(token), read(), read())

        return read()

    @staticmethod
    def clone(root):
        copies = {}

        def copy(n):
            if n is None:
                return None
            if n in copies:
                return copies[n]
            c = Node(n.val)
            copies[n] = c
            c.neighbors = [copy(v) for v in n.neighbors]
            return c

        return copy(root)

