    def max_path(root):
        best = -(10**30)

        def gain(n):
            nonlocal best
            if not n:
                return 0
            l = max(0, gain(n.left))
            r = max(0, gain(n.right))
            best = max(best, n.val + l + r)
            return n.val + max(l, r)

        gain(root)
        return best

