function findWords(board, words) {
  const out = [];
  for (const word of new Set(words)) {
    const rows = board.length,
      cols = board[0].length,
      used = Array.from({ length: rows }, () => Array(cols).fill(false));
    function visit(r, c, i) {
      if (
        r < 0 ||
        r >= rows ||
        c < 0 ||
        c >= cols ||
        used[r][c] ||
        board[r][c] !== word[i]
      )
        return false;
      if (i === word.length - 1) return true;
      used[r][c] = true;
      const ok =
        visit(r - 1, c, i + 1) ||
        visit(r + 1, c, i + 1) ||
        visit(r, c - 1, i + 1) ||
        visit(r, c + 1, i + 1);
      used[r][c] = false;
      return ok;
    }
    let found = false;
    for (let r = 0; r < rows && !found; r++)
      for (let c = 0; c < cols && !found; c++) found = visit(r, c, 0);
    if (found) out.push(word);
  }
  return out;
}

