def find_words(board: list[str], words: list[str]) -> list[str]:
    trie = {}
    for word in words:
        node = trie
        for c in word:
            node = node.setdefault(c, {})
        node["$"] = word
    rows, cols = len(board), len(board[0])
    used = set()
    out = []

    def visit(r, c, node):
        if not (0 <= r < rows and 0 <= c < cols) or (r, c) in used:
            return
        ch = board[r][c]
        if ch not in node:
            return
        child = node[ch]
        if "$" in child:
            out.append(child.pop("$"))
        used.add((r, c))
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            visit(r + dr, c + dc, child)
        used.remove((r, c))
        if not child:
            del node[ch]

    for r in range(rows):
        for c in range(cols):
            visit(r, c, trie)
    return out


