public class Solution {
  public String[] findWords(String[] board, String[] words) {
    List<String> out = new ArrayList<>();
    for (String word : new HashSet<>(Arrays.asList(words))) {
      int rows = board.length, cols = board[0].length();
      boolean[][] used = new boolean[rows][cols];
      class Search {
        boolean visit(int r, int c, int i) {
          if (r < 0 || r >= rows || c < 0 || c >= cols || used[r][c]
              || board[r].charAt(c) != word.charAt(i))
            return false;
          if (i == word.length() - 1)
            return true;
          used[r][c] = true;
          boolean ok = visit(r - 1, c, i + 1) || visit(r + 1, c, i + 1) || visit(r, c - 1, i + 1)
              || visit(r, c + 1, i + 1);
          used[r][c] = false;
          return ok;
        }
      }
      Search search = new Search();
      boolean found = false;
      for (int r = 0; r < rows && !found; r++)
        for (int c = 0; c < cols && !found; c++) found = search.visit(r, c, 0);
      if (found)
        out.add(word);
    }
    return out.toArray(String[] ::new);
  }
}

