    if (pre.length == 0)
      return null;
    int i = 0;
    while (ino[i] != pre[0]) i++;
    TreeNode n = new TreeNode(pre[0]);
    n.left = build(Arrays.copyOfRange(pre, 1, i + 1), Arrays.copyOfRange(ino, 0, i));
    n.right = build(
        Arrays.copyOfRange(pre, i + 1, pre.length), Arrays.copyOfRange(ino, i + 1, ino.length));
