    while (!q.isEmpty()) {
      out.add(q.stream().mapToInt(n -> n.val).toArray());
      List<TreeNode> next = new ArrayList<>();
      for (TreeNode n : q) {
        if (n.left != null)
          next.add(n.left);
        if (n.right != null)
          next.add(n.right);
      }
      q = next;
    }
