        count++;
        seen[r][c] = true;
        const q = [[r, c]];
        for (let j = 0; j < q.length; j++)
          for (let i = 0; i < 4; i++) {
            const u = q[j][0] + dr[i],
              v = q[j][1] + dc[i];
            if (
              u >= 0 &&
              u < rows &&
              v >= 0 &&
              v < cols &&
              grid[u][v] === "1" &&
              !seen[u][v]
            ) {
              seen[u][v] = true;
              q.push([u, v]);
            }
          }
      }
  return count;
}

