def num_islands(grid: list[str]) -> int:
    rows, cols = len(grid), len(grid[0])
    seen = set()
    count = 0
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != "1" or (r, c) in seen:
                continue
            count += 1
            seen.add((r, c))
            q = deque([(r, c)])
            while q:
                i, j = q.popleft()
                for u, v in [(i - 1, j), (i + 1, j), (i, j - 1), (i, j + 1)]:
                    if (
                        0 <= u < rows
                        and 0 <= v < cols
                        and grid[u][v] == "1"
                        and (u, v) not in seen
                    ):
                        seen.add((u, v))
                        q.append((u, v))
    return count


