TreeNode* build(std::vector<int> pre, std::vector<int> ino) {
  if (pre.empty()) return nullptr;
  auto i = std::find(ino.begin(), ino.end(), pre[0]) - ino.begin();
  auto n = new TreeNode(pre[0]);
  n->left = build({pre.begin() + 1, pre.begin() + i + 1},
                  {ino.begin(), ino.begin() + i});
  n->right =
      build({pre.begin() + i + 1, pre.end()}, {ino.begin() + i + 1, ino.end()});
  return n;
