class Solution {
 public:
  int NumIslands(std::vector<std::string>& grid) {
    int rows = static_cast<int>(grid.size()),
        cols = static_cast<int>(grid[0].size()), count = 0;
    std::vector<std::vector<bool>> seen(rows, std::vector<bool>(cols));
    int dr[] = {-1, 1, 0, 0}, dc[] = {0, 0, -1, 1};
    for (int r = 0; r < rows; r++)
      for (int c = 0; c < cols; c++)
        if (grid[r][c] == '1' && !seen[r][c]) {
          count++;
          seen[r][c] = true;
          std::queue<std::pair<int, int>> q;
          q.emplace(r, c);
          while (!q.empty()) {
            auto p = q.front();
            q.pop();
            for (int i = 0; i < 4; i++) {
              int u = p.first + dr[i], v = p.second + dc[i];
              if (u >= 0 && u < rows && v >= 0 && v < cols &&
                  grid[u][v] == '1' && !seen[u][v]) {
                seen[u][v] = true;
                q.emplace(u, v);
              }
            }
          }
        }
