    def build(pre, ino):
        if not pre:
            return None
        i = ino.index(pre[0])
        return TreeNode(
            pre[0],
            Probe.build(pre[1 : i + 1], ino[:i]),
            Probe.build(pre[i + 1 :], ino[i + 1 :]),
        )

