    def inorder(n):
        return Probe.inorder(n.left) + [n.val] + Probe.inorder(n.right) if n else []

    @staticmethod
    def max_path(root):
        best = -(10**30)

        def gain(n):
            nonlocal best
            if not n:
                return 0
            l = max(0, gain(n.left))
            r = max(0, gain(n.right))
            best = max(best, n.val + l + r)
            return n.val + max(l, r)

        gain(root)
        return best

    @staticmethod
    def serialize(n):
        return (
            str(n.val) + " " + Probe.serialize(n.left) + Probe.serialize(n.right)
            if n
            else "# "
        )

    @staticmethod
    def deserialize(s):
        tokens = iter(s.split())

        def read():
            token = next(tokens)
            return None if token == "#" else TreeNode(int(token), read(), read())

        return read()

    @staticmethod
    def clone(root):
        copies = {}

        def copy(n):
            if n is None:
                return None
            if n in copies:
                return copies[n]
            c = Node(n.val)
            copies[n] = c
            c.neighbors = [copy(v) for v in n.neighbors]
