def pacific_atlantic(heights: list[list[int]]) -> list[list[int]]:
    rows, cols = len(heights), len(heights[0])

    def flood(cells):
        seen = set(cells)
        q = deque(seen)
        while q:
            r, c = q.popleft()
            for u, v in [(r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)]:
                if (
                    0 <= u < rows
                    and 0 <= v < cols
                    and (u, v) not in seen
                    and heights[u][v] >= heights[r][c]
                ):
                    seen.add((u, v))
                    q.append((u, v))
        return seen

    a = flood([(r, 0) for r in range(rows)] + [(0, c) for c in range(cols)])
    b = flood(
        [(r, cols - 1) for r in range(rows)] + [(rows - 1, c) for c in range(cols)]
    )
    return [list(p) for p in sorted(a & b)]


