class Solution {
 public:
  std::vector<std::vector<int>> PacificAtlantic(
      std::vector<std::vector<int>>& heights) {
    int rows = static_cast<int>(heights.size()),
        cols = static_cast<int>(heights[0].size());
    auto flood = [&](bool pacific) {
      std::vector<std::vector<bool>> seen(rows, std::vector<bool>(cols));
      std::queue<std::pair<int, int>> q;
      auto add = [&](int r, int c) {
        if (!seen[r][c]) {
          seen[r][c] = true;
          q.emplace(r, c);
        }
      };
      for (int r = 0; r < rows; r++) add(r, pacific ? 0 : cols - 1);
      for (int c = 0; c < cols; c++) add(pacific ? 0 : rows - 1, c);
      int dr[] = {-1, 1, 0, 0}, dc[] = {0, 0, -1, 1};
      while (!q.empty()) {
        auto p = q.front();
        q.pop();
        for (int i = 0; i < 4; i++) {
          int u = p.first + dr[i], v = p.second + dc[i];
          if (u >= 0 && u < rows && v >= 0 && v < cols && !seen[u][v] &&
              heights[u][v] >= heights[p.first][p.second])
            add(u, v);
        }
      }
      return seen;
    };
    auto a = flood(true), b = flood(false);
    std::vector<std::vector<int>> out;
    for (int r = 0; r < rows; r++)
      for (int c = 0; c < cols; c++)
        if (a[r][c] && b[r][c]) out.push_back({r, c});
    return out;
  }
};

