    used = set()

    def visit(r, c, i):
        if (
            not (0 <= r < rows and 0 <= c < cols)
            or (r, c) in used
            or board[r][c] != word[i]
        ):
            return False
        if i == len(word) - 1:
            return True
        used.add((r, c))
        found = any(
            visit(r + dr, c + dc, i + 1)
            for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]
        )
        used.remove((r, c))
        return found

    return any(visit(r, c, 0) for r in range(rows) for c in range(cols))


def component_count(n, edges):
    parent = list(range(n))
    count = n

    def find(v):
        while v != parent[v]:
            parent[v] = parent[parent[v]]
            v = parent[v]
        return v

    for u, v in edges:
        a, b = find(u), find(v)
        if a != b:
            parent[a] = b
            count -= 1
    return count

