function validTree(n, edges) {
  if (n === 0 || edges.length !== n - 1) return false;
  const parent = Array.from({ length: n }, (_, i) => i);
  function find(v) {
    while (v !== parent[v]) {
      parent[v] = parent[parent[v]];
      v = parent[v];
    }
    return v;
  }
  let count = n;
  for (const [u, v] of edges) {
    const a = find(u),
      b = find(v);
    if (a !== b) {
      parent[a] = b;
      count--;
    }
  }
  return count == 1;
}

