            degree[c]++;
        var ready = new SortedSet<char>(degree.Where(p => p.Value == 0).Select(p => p.Key));
        var outp = new List<char>();
        while (ready.Count > 0)
        {
            char c = ready.Min;
            ready.Remove(c);
            outp.Add(c);
            foreach (char next in graph[c])
            if (--degree[next] == 0)
                ready.Add(next);
        }
        return outp.Count == graph.Count ? new string(outp.ToArray()) : "";
    }
}

