function alienOrder(words) {
  const graph = new Map();
  for (const c of words.join("")) if (!graph.has(c)) graph.set(c, new Set());
  for (let i = 1; i < words.length; i++) {
    const a = words[i - 1],
      b = words[i];
    let j = 0;
    while (j < Math.min(a.length, b.length) && a[j] === b[j]) j++;
    if (j === Math.min(a.length, b.length)) {
      if (a.length > b.length) return "";
    } else graph.get(a[j]).add(b[j]);
  }
  const degree = new Map([...graph.keys()].map((c) => [c, 0]));
  for (const row of graph.values())
    for (const c of row) degree.set(c, degree.get(c) + 1);
  const ready = [...degree].filter((p) => p[1] === 0).map((p) => p[0]),
    out = [];
  while (ready.length) {
    ready.sort();
    const c = ready.shift();
    out.push(c);
    for (const next of graph.get(c)) {
      degree.set(next, degree.get(next) - 1);
      if (!degree.get(next)) ready.push(next);
    }
  }
  return out.length === graph.size ? out.join("") : "";
}

