public class Solution {
  public String alienOrder(String[] words) {
    Map<Character, Set<Character>> graph = new HashMap<>();
    for (String w : words)
      for (char c : w.toCharArray()) graph.computeIfAbsent(c, k -> new HashSet<>());
    for (int i = 1; i < words.length; i++) {
      String a = words[i - 1], b = words[i];
      int j = 0;
      while (j < Math.min(a.length(), b.length()) && a.charAt(j) == b.charAt(j)) j++;
      if (j == Math.min(a.length(), b.length())) {
        if (a.length() > b.length())
          return "";
      } else
        graph.get(a.charAt(j)).add(b.charAt(j));
    }
    Map<Character, Integer> degree = new HashMap<>();
    for (char c : graph.keySet()) degree.put(c, 0);
    for (Set<Character> row : graph.values())
      for (char c : row) degree.put(c, degree.get(c) + 1);
    PriorityQueue<Character> ready = new PriorityQueue<>();
    for (var e : degree.entrySet())
      if (e.getValue() == 0)
        ready.add(e.getKey());
    StringBuilder out = new StringBuilder();
    while (!ready.isEmpty()) {
      char c = ready.remove();
      out.append(c);
      for (char next : graph.get(c)) {
        degree.put(next, degree.get(next) - 1);
        if (degree.get(next) == 0)
          ready.add(next);
      }
    }
    return out.length() == graph.size() ? out.toString() : "";
  }
}

