def rob(nums: list[int]) -> int:
    def run(values):
        a = b = 0
        for v in values:
            a, b = b, max(b, a + v)
        return b

    return (
        (nums[0] if nums else 0)
        if len(nums) <= 1
        else max(run(nums[:-1]), run(nums[1:]))
    )


