public class Solution
{
    public int LengthOfLIS(int[] nums)
    {
        var tails = new List<int>();
        foreach (int v in nums)
        {
            int l = 0, r = tails.Count;
            while (l < r)
            {
                int mid = l + (r - l) / 2;
                if (tails[mid] < v)
                    l = mid + 1;
                else
                    r = mid;
            }
            if (l == tails.Count)
                tails.Add(v);
            else
                tails[l] = v;
        }
        return tails.Count;
    }
}

