public class Solution {
  public int lengthOfLIS(int[] nums) {
    int[] tails = new int[nums.length];
    int length = 0;
    for (int v : nums) {
      int l = 0, r = length;
      while (l < r) {
        int mid = l + (r - l) / 2;
        if (tails[mid] < v)
          l = mid + 1;
        else
          r = mid;
      }
      tails[l] = v;
      if (l == length)
        length++;
    }
    return length;
  }
}

