class Solution {
 public:
  int CombinationSum4(std::vector<int>& nums, int target) {
    std::vector<uint64_t> dp(target + 1);
    dp[0] = 1;
    for (int v = 1; v <= target; v++)
      for (int c : nums)
        if (c <= v) dp[v] += dp[v - c];
    return static_cast<int>(dp[target]);
  }
};

