def word_exists(board, word):
    rows, cols = len(board), len(board[0])
    used = set()

    def visit(r, c, i):
        if (
            not (0 <= r < rows and 0 <= c < cols)
            or (r, c) in used
            or board[r][c] != word[i]
        ):
            return False
        if i == len(word) - 1:
            return True
