    TreeNode n = new TreeNode(Integer.parseInt(s));
    n.left = read(q);
    n.right = read(q);
    return n;
  }
  static TreeNode deserialize(String s) {
    return read(new ArrayDeque<>(Arrays.asList(s.trim().split(" +"))));
